import { Group, Mesh, PlaneGeometry, DoubleSide, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, sub, add, color, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // ---------- Background Plane with Edge Fade ----------
  const bgGeom = new PlaneGeometry(7, 0.35);
  const surfaceCol = color('#111117');
  const backgroundCol = color('#0b0b10');

  const uvNode = uv();
  const x = uvNode.x;
  const fadeWidth = float(0.6 / 7); // normalized width
  const leftFade = smoothstep(float(0), fadeWidth, x);
  const rightFade = smoothstep(float(1).sub(fadeWidth), float(1), x);
  const mask = sub(float(1), add(leftFade, rightFade));
  const bgColor = mix(surfaceCol, backgroundCol, mask);

  const bgMat = new MeshStandardNodeMaterial({
    color: bgColor,
    metalness: 0.2,
    roughness: 0.6,
    side: DoubleSide,
    transparent: true,
  });
  const bgMesh = new Mesh(bgGeom, bgMat);
  root.add(bgMesh);

  // ---------- Hairlines ----------
  const hairHeight = 0.006;
  const hairGeom = new PlaneGeometry(7, hairHeight);
  const hairCol = color('#23232b');
  const hairMat = new MeshBasicNodeMaterial({ color: hairCol, side: DoubleSide });
  const topHair = new Mesh(hairGeom, hairMat);
  topHair.position.set(0, 0.35 / 2 - hairHeight / 2, 0);
  const bottomHair = new Mesh(hairGeom, hairMat);
  bottomHair.position.set(0, -0.35 / 2 + hairHeight / 2, 0);
  root.add(topHair);
  root.add(bottomHair);

  // ---------- Ticker Strip ----------
  const scrollContainer = new Group();
  scrollContainer.position.set(0, 0, 0.02);
  root.add(scrollContainer);

  const stripA = new Group();
  const stripB = new Group();
  scrollContainer.add(stripA);
  scrollContainer.add(stripB);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const tickGeom = new PlaneGeometry(0.02, 0.14);
  const accentCol = color('#ff2a38');
  const tickMat = new MeshStandardNodeMaterial({
    color: accentCol,
    emissive: accentCol,
    emissiveIntensity: 1.5,
    metalness: 0,
    roughness: 0.5,
    side: DoubleSide,
  });

  const baseUnit = 0.25;
  const gap = baseUnit * 2; // 0.5 units between items
  let cursor = 0;

  function addItem(targetGroup) {
    for (const item of items) {
      const txt = ctx.fontAtlas.createText(item.text, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: 0.06 * 13,
      });
      txt.position.set(cursor, 0, 0);
      targetGroup.add(txt);

      const tick = new Mesh(tickGeom, tickMat);
      tick.position.set(cursor + 0.2, 0, 0);
      targetGroup.add(tick);

      // Approximate advance (text width ~1.5 units)
      cursor += 1.5 + 0.2 + gap;
    }
  }

  addItem(stripA);
  const totalLength = cursor;
  stripB.position.x = totalLength;

  // ---------- Apply Cinematic Primitives ----------
  const appliedPrimitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(scrollContainer, prim.params);
        appliedPrimitives.push(result);
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    bgGeom.dispose();
    bgMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    tickGeom.dispose();
    tickMat.dispose();

    // Dispose any textures created by fontAtlas (handled by atlas)

    // Cleanup primitives
    for (const p of appliedPrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Kill GSAP timelines if any (none created here)
    gsap.globalTimeline.clear();
  };

  return root;
}
